<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
const experiences={Wildlife:['Safari & wildlife','Guided wildlife experience in a suitable national-park circuit'],Culture:['Culture & heritage','Community, heritage site or local craft experience'],Nature:['Nature escape','Scenic landscape, waterfall, forest or viewpoint'],Beach:['Coastal day','Beach relaxation and water-based activity'],City:['City discovery','Landmarks, markets and guided city exploration'],Food:['Tanzanian food trail','Local dishes, market tasting and restaurant experience']};
const money=n=>new Intl.NumberFormat('en-TZ').format(Math.round(n))+' TZS';
function generate(){
 const days=Math.max(1,Math.min(21,parseInt($('#days').val(),10)||5)),people=Math.max(1,parseInt($('#people').val(),10)||2),start=$('#start').val(),style=$('#style').val();let interests=$('.interest:checked').map(function(){return this.value}).get();if(!interests.length)interests=['Culture','Nature'];
 let html='';for(let i=1;i<=days;i++){let title,desc,location;if(i===1){title='Arrival & local discovery';desc=`Arrive in ${start}, check in, settle down and explore a nearby experience.`;location=start}else if(i===days){title='Final morning & departure';desc='Breakfast, optional shopping, checkout and arranged transfer to your departure point.';location='Departure'}else{const k=interests[(i-2)%interests.length],x=experiences[k];title=x[0];desc=x[1]+'. Keep travel time realistic and return to your accommodation in the evening.';location=k}html+=`<div class="col-12"><article class="card day p-4"><div class="d-flex gap-3"><div class="day-num flex-shrink-0">${i}</div><div class="flex-grow-1"><div class="d-flex flex-column flex-md-row justify-content-between gap-2"><div><span class="badge badge-soft rounded-pill">${location}</span><h3 class="h5 fw-bold mt-2 mb-2">${title}</h3></div><span class="small-note"><i class="bi bi-clock"></i> Flexible timing</span></div><p class="text-secondary mb-0">${desc}</p></div></div></article></div>`}
 $('#itinerary-list').html(html);
 const mult={budget:.72,standard:1,comfort:1.55}[style],rooms=Math.ceil(people/2),nights=Math.max(1,days-1);const accommodation=65000*rooms*nights*mult,transport=55000*days*mult,activities=70000*people*Math.max(1,days-2)*mult,food=45000*people*days*mult,total=accommodation+transport+activities+food;
 const cards=[['Accommodation',accommodation,'bi-building'],['Transport',transport,'bi-bus-front'],['Activities',activities,'bi-compass'],['Food',food,'bi-cup-hot'],['Estimated total',total,'bi-calculator']];$('#costs').html(cards.map((c,i)=>`<div class="col-md-6 col-lg"><div class="card cost p-4 h-100 ${i===4?'text-white':''}" style="${i===4?'background:#063b29':''}"><i class="bi ${c[2]} ${i===4?'text-warning':'text-success'} fs-4"></i><small class="d-block mt-3 ${i===4?'text-white-50':'text-secondary'}">${c[0]}</small><strong class="fs-5 d-block mt-1">${money(c[1])}</strong></div></div>`).join(''));
}
$(function(){$('#year').text(new Date().getFullYear());$('.chip').on('click',function(){const input=$(this).find('input');if(event.target!==input[0])input.prop('checked',!input.prop('checked'));$(this).toggleClass('active',input.prop('checked'))});$('#generate').on('click',function(){const b=$(this);b.addClass('loading').html('<span class="spinner-border spinner-border-sm me-2"></span>Building journey...');setTimeout(()=>{generate();b.removeClass('loading').html('Generate journey <i class="bi bi-magic ms-1"></i>');document.querySelector('#itinerary-list').scrollIntoView({behavior:'smooth',block:'start'})},350)});generate()});
</script>
